PROGRAMS = {'inheritance1.py': '# Employee and Manager inheritance\n\nclass Employee:\n    def __init__(self, emp_id, name, salary):\n        self.emp_id = emp_id\n        self.name = name\n        self.salary = salary\n\n    def display(self):\n        print(self.emp_id, self.name, self.salary)\n\n\nclass Manager(Employee):\n    def __init__(self, emp_id, name, salary, department):\n        super().__init__(emp_id, name, salary)\n        self.department = department\n\n    def annual_salary(self):\n        return self.salary * 12\n\n    def display(self):\n        super().display()\n        print("Department:", self.department)\n        print("Annual Salary:", self.annual_salary())\n\n\nmanager = Manager(101, "Amit", 50000, "IT")\nmanager.display()\n', 'inheritance2.py': '# Vehicle and Car inheritance\n\nclass Vehicle:\n    def __init__(self, brand, model):\n        self.brand = brand\n        self.model = model\n\n    def display(self):\n        print("Brand:", self.brand)\n        print("Model:", self.model)\n\n\nclass Car(Vehicle):\n    def __init__(self, brand, model, fuel_type, price):\n        super().__init__(brand, model)\n        self.fuel_type = fuel_type\n        self.price = price\n\n    def discounted_price(self, discount):\n        return self.price - self.price * discount / 100\n\n    def display(self):\n        super().display()\n        print("Fuel Type:", self.fuel_type)\n        print("Price:", self.price)\n        print("Discounted Price:", self.discounted_price(10))\n\n\ncar = Car("Tata", "Nexon", "Petrol", 900000)\ncar.display()\n', 'inheritance3.py': '# Student multiple inheritance\n\nclass Academic:\n    def __init__(self, marks):\n        self.marks = marks\n\n\nclass Sports:\n    def __init__(self, points):\n        self.points = points\n\n\nclass Student(Academic, Sports):\n    def __init__(self, marks, points):\n        Academic.__init__(self, marks)\n        Sports.__init__(self, points)\n\n    def performance(self):\n        return sum(self.marks) + self.points\n\n\nstudent = Student([80, 75, 85], 20)\n\nprint("Academic Marks:", student.marks)\nprint("Sports Points:", student.points)\nprint("Overall Performance:", student.performance())\n', 'inheritance4.py': '# Employee multiple inheritance\n\nclass PersonalDetails:\n    def __init__(self, name, age):\n        self.name = name\n        self.age = age\n\n\nclass ProfessionalDetails:\n    def __init__(self, emp_id, designation, salary):\n        self.emp_id = emp_id\n        self.designation = designation\n        self.salary = salary\n\n\nclass Employee(PersonalDetails, ProfessionalDetails):\n    def __init__(self, name, age, emp_id, designation, salary):\n        PersonalDetails.__init__(self, name, age)\n        ProfessionalDetails.__init__(self, emp_id, designation, salary)\n\n    def display(self):\n        print("Name:", self.name)\n        print("Age:", self.age)\n        print("Employee ID:", self.emp_id)\n        print("Designation:", self.designation)\n        print("Salary:", self.salary)\n\n\nemployee = Employee("Amit", 25, 101, "Developer", 50000)\nemployee.display()\n', 'inheritance5.py': '# Person, Student and ResearchStudent inheritance\n\nclass Person:\n    def __init__(self, name, age):\n        self.name = name\n        self.age = age\n\n\nclass Student(Person):\n    def __init__(self, name, age, roll_no, course):\n        super().__init__(name, age)\n        self.roll_no = roll_no\n        self.course = course\n\n\nclass ResearchStudent(Student):\n    def __init__(self, name, age, roll_no, course, topic, guide):\n        super().__init__(name, age, roll_no, course)\n        self.topic = topic\n        self.guide = guide\n\n    def display(self):\n        print("Name:", self.name)\n        print("Age:", self.age)\n        print("Roll No:", self.roll_no)\n        print("Course:", self.course)\n        print("Research Topic:", self.topic)\n        print("Guide:", self.guide)\n\n\nstudent = ResearchStudent(\n    "Amit", 23, 101, "B.Tech", "Artificial Intelligence", "Dr. Sharma"\n)\nstudent.display()\n', 'inheritance6.py': '# Bank account multilevel inheritance\n\nclass BankAccount:\n    def __init__(self, account_no, balance):\n        self.account_no = account_no\n        self.balance = balance\n\n\nclass SavingsAccount(BankAccount):\n    def __init__(self, account_no, balance, interest_rate):\n        super().__init__(account_no, balance)\n        self.interest_rate = interest_rate\n\n    def calculate_interest(self):\n        return self.balance * self.interest_rate / 100\n\n\nclass PremiumSavingsAccount(SavingsAccount):\n    def __init__(self, account_no, balance, interest_rate, benefits):\n        super().__init__(account_no, balance, interest_rate)\n        self.benefits = benefits\n\n    def display(self):\n        print("Account:", self.account_no)\n        print("Balance:", self.balance)\n        print("Interest:", self.calculate_interest())\n        print("Benefits:", self.benefits)\n\n\naccount = PremiumSavingsAccount(1001, 50000, 6, "Free Insurance")\naccount.display()\n', 'inheritance7.py': '# Shape hierarchical inheritance\n\nclass Shape:\n    def __init__(self, name):\n        self.name = name\n\n    def display_name(self):\n        print("Shape:", self.name)\n\n\nclass Circle(Shape):\n    def area(self, radius):\n        return 3.14 * radius * radius\n\n\nclass Rectangle(Shape):\n    def area(self, length, breadth):\n        return length * breadth\n\n\nclass Triangle(Shape):\n    def area(self, base, height):\n        return 0.5 * base * height\n\n\nCircle("Circle").display_name()\nprint("Circle Area:", Circle("Circle").area(5))\n\nRectangle("Rectangle").display_name()\nprint("Rectangle Area:", Rectangle("Rectangle").area(10, 5))\n\nTriangle("Triangle").display_name()\nprint("Triangle Area:", Triangle("Triangle").area(10, 6))\n', 'inheritance8.py': '# Employee role-based inheritance\n\nclass Employee:\n    def __init__(self, emp_id, name, basic_salary):\n        self.emp_id = emp_id\n        self.name = name\n        self.basic_salary = basic_salary\n\n    def salary(self):\n        return self.basic_salary\n\n\nclass Manager(Employee):\n    def salary(self):\n        return self.basic_salary + self.basic_salary * 0.30\n\n\nclass Developer(Employee):\n    def salary(self):\n        return self.basic_salary + self.basic_salary * 0.20\n\n\nclass Tester(Employee):\n    def salary(self):\n        return self.basic_salary + self.basic_salary * 0.15\n\n\nemployees = [\n    Manager(1, "Amit", 50000),\n    Developer(2, "Rahul", 40000),\n    Tester(3, "Sneha", 35000)\n]\n\nfor employee in employees:\n    print(employee.name, employee.salary())\n', 'inheritance9.py': '# Multiple and hierarchical inheritance\n\nclass Person:\n    def __init__(self, name):\n        self.name = name\n\n\nclass Student(Person):\n    def study(self):\n        print(self.name, "is studying")\n\n\nclass Faculty(Person):\n    def teach(self):\n        print(self.name, "is teaching")\n\n\nclass TeachingAssistant(Student, Faculty):\n    def work(self):\n        self.study()\n        self.teach()\n\n\nassistant = TeachingAssistant("Amit")\nassistant.work()\n', 'inheritance10.py': '# Combination of inheritance types\n\nclass Vehicle:\n    def __init__(self, brand):\n        self.brand = brand\n\n\nclass Car(Vehicle):\n    def drive(self):\n        print(self.brand, "Car is driving")\n\n\nclass Bike(Vehicle):\n    def ride(self):\n        print(self.brand, "Bike is riding")\n\n\nclass SportsCar(Car):\n    def speed(self):\n        print(self.brand, "Sports car is fast")\n\n\nclass ElectricBike(Bike):\n    def battery(self):\n        print(self.brand, "Electric bike uses battery")\n\n\nSportsCar("BMW").speed()\nElectricBike("Ola").battery()\n', 'inheritance11.py': '# Student result inheritance\n\nclass Student:\n    def __init__(self, roll_no, name, course):\n        self.roll_no = roll_no\n        self.name = name\n        self.course = course\n\n\nclass Result(Student):\n    def __init__(self, roll_no, name, course, marks):\n        super().__init__(roll_no, name, course)\n        self.marks = marks\n\n    def total(self):\n        return sum(self.marks)\n\n    def percentage(self):\n        return self.total() / len(self.marks)\n\n    def grade(self):\n        p = self.percentage()\n        if p >= 75:\n            return "A"\n        elif p >= 60:\n            return "B"\n        elif p >= 50:\n            return "C"\n        return "D"\n\n\nresult = Result(101, "Amit", "B.Tech", [80, 75, 85])\n\nprint("Total:", result.total())\nprint("Percentage:", result.percentage())\nprint("Grade:", result.grade())\n', 'inheritance12.py': '# Electronic product inheritance\n\nclass Product:\n    def __init__(self, product_id, name, price):\n        self.product_id = product_id\n        self.name = name\n        self.price = price\n\n\nclass ElectronicProduct(Product):\n    def __init__(self, product_id, name, price, brand, warranty):\n        super().__init__(product_id, name, price)\n        self.brand = brand\n        self.warranty = warranty\n\n    def final_price(self, discount):\n        return self.price - self.price * discount / 100\n\n    def display(self):\n        print("Product:", self.name)\n        print("Brand:", self.brand)\n        print("Warranty:", self.warranty)\n        print("Final Price:", self.final_price(10))\n\n\nproduct = ElectronicProduct(101, "Laptop", 60000, "HP", "2 Years")\nproduct.display()\n', 'inheritance13.py': '# Printer and Scanner multiple inheritance\n\nclass Printer:\n    def print_document(self):\n        print("Printing document")\n\n\nclass Scanner:\n    def scan_document(self):\n        print("Scanning document")\n\n\nclass MultifunctionDevice(Printer, Scanner):\n    pass\n\n\ndevice = MultifunctionDevice()\ndevice.print_document()\ndevice.scan_document()\n', 'inheritance14.py': '# Camera and Phone multiple inheritance\n\nclass Camera:\n    def take_photo(self):\n        print("Photo taken")\n\n\nclass Phone:\n    def make_call(self):\n        print("Calling...")\n\n\nclass Smartphone(Camera, Phone):\n    pass\n\n\nphone = Smartphone()\nphone.take_photo()\nphone.make_call()\n', 'inheritance15.py': '# Research student inheritance\n\nclass Person:\n    def __init__(self, name, age):\n        self.name = name\n        self.age = age\n\n\nclass Student(Person):\n    def __init__(self, name, age, roll_no, course):\n        super().__init__(name, age)\n        self.roll_no = roll_no\n        self.course = course\n\n\nclass ResearchStudent(Student):\n    def __init__(self, name, age, roll_no, course, topic, guide):\n        super().__init__(name, age, roll_no, course)\n        self.topic = topic\n        self.guide = guide\n\n    def display(self):\n        print(self.name, self.age, self.roll_no, self.course)\n        print(self.topic, self.guide)\n\n\nstudent = ResearchStudent(\n    "Amit", 23, 101, "B.Tech", "Machine Learning", "Dr. Sharma"\n)\nstudent.display()\n', 'inheritance16.py': '# Research student inheritance\n\nclass Person:\n    def __init__(self, name, age):\n        self.name = name\n        self.age = age\n\n\nclass Student(Person):\n    def __init__(self, name, age, roll_no, course):\n        super().__init__(name, age)\n        self.roll_no = roll_no\n        self.course = course\n\n\nclass ResearchStudent(Student):\n    def __init__(self, name, age, roll_no, course, topic, guide):\n        super().__init__(name, age, roll_no, course)\n        self.topic = topic\n        self.guide = guide\n\n    def display(self):\n        print("Name:", self.name)\n        print("Age:", self.age)\n        print("Roll No:", self.roll_no)\n        print("Course:", self.course)\n        print("Topic:", self.topic)\n        print("Guide:", self.guide)\n\n\nstudent = ResearchStudent(\n    "Rahul", 24, 102, "M.Tech", "Cloud Computing", "Dr. Patil"\n)\nstudent.display()\n', 'inheritance17.py': '# Animal hierarchical inheritance\n\nclass Animal:\n    def eat(self):\n        print("Animal eats food")\n\n\nclass Dog(Animal):\n    def sound(self):\n        print("Dog: Bark")\n\n\nclass Cat(Animal):\n    def sound(self):\n        print("Cat: Meow")\n\n\nclass Cow(Animal):\n    def sound(self):\n        print("Cow: Moo")\n\n\nfor animal in [Dog(), Cat(), Cow()]:\n    animal.eat()\n    animal.sound()\n', 'inheritance18.py': '# Medical multiple and hierarchical inheritance\n\nclass Person:\n    def __init__(self, name):\n        self.name = name\n\n\nclass Doctor(Person):\n    def treat(self):\n        print(self.name, "treats patients")\n\n\nclass Patient(Person):\n    def visit(self):\n        print(self.name, "visits hospital")\n\n\nclass Surgeon(Doctor):\n    def surgery(self):\n        print(self.name, "performs surgery")\n\n\nclass MedicalResearcher(Doctor):\n    def research(self):\n        print(self.name, "does medical research")\n\n\nSurgeon("Dr. Amit").surgery()\nMedicalResearcher("Dr. Rahul").research()\nPatient("Sneha").visit()\n', 'polymorphism1.py': '# Shape area polymorphism\n\nimport math\n\nclass Shape:\n    def area(self):\n        pass\n\n\nclass Circle(Shape):\n    def area(self):\n        return math.pi * 5 * 5\n\n\nclass Rectangle(Shape):\n    def area(self):\n        return 10 * 5\n\n\nclass Triangle(Shape):\n    def area(self):\n        return 0.5 * 10 * 6\n\n\nfor shape in [Circle(), Rectangle(), Triangle()]:\n    print("Area:", shape.area())\n', 'polymorphism2.py': '# Employee salary polymorphism\n\nclass Employee:\n    def calculate_salary(self):\n        pass\n\n\nclass Manager(Employee):\n    def calculate_salary(self):\n        return 50000 + 15000\n\n\nclass Developer(Employee):\n    def calculate_salary(self):\n        return 40000 + 8000\n\n\nclass Tester(Employee):\n    def calculate_salary(self):\n        return 35000 + 5000\n\n\nfor employee in [Manager(), Developer(), Tester()]:\n    print("Salary:", employee.calculate_salary())\n', 'polymorphism3.py': '# Vehicle start polymorphism\n\nclass Vehicle:\n    def start(self):\n        pass\n\n\nclass Car(Vehicle):\n    def start(self):\n        print("Car starts with key")\n\n\nclass Bike(Vehicle):\n    def start(self):\n        print("Bike starts with button")\n\n\nclass Bus(Vehicle):\n    def start(self):\n        print("Bus starts with engine")\n\n\nfor vehicle in [Car(), Bike(), Bus()]:\n    vehicle.start()\n', 'polymorphism4.py': '# Animal sound polymorphism\n\nclass Animal:\n    def sound(self):\n        pass\n\n\nclass Dog(Animal):\n    def sound(self):\n        print("Dog: Bark")\n\n\nclass Cat(Animal):\n    def sound(self):\n        print("Cat: Meow")\n\n\nclass Cow(Animal):\n    def sound(self):\n        print("Cow: Moo")\n\n\nclass Lion(Animal):\n    def sound(self):\n        print("Lion: Roar")\n\n\nfor animal in [Dog(), Cat(), Cow(), Lion()]:\n    animal.sound()\n', 'polymorphism5.py': '# Notification polymorphism\n\nclass Notification:\n    def send(self):\n        pass\n\n\nclass EmailNotification(Notification):\n    def send(self):\n        print("Email notification sent")\n\n\nclass SMSNotification(Notification):\n    def send(self):\n        print("SMS notification sent")\n\n\nclass PushNotification(Notification):\n    def send(self):\n        print("Push notification sent")\n\n\nfor notification in [\n    EmailNotification(),\n    SMSNotification(),\n    PushNotification()\n]:\n    notification.send()\n', 'polymorphism6.py': '# Student grade polymorphism\n\nclass Student:\n    def calculate_grade(self, marks):\n        pass\n\n\nclass EngineeringStudent(Student):\n    def calculate_grade(self, marks):\n        return "A" if marks >= 75 else "B"\n\n\nclass MedicalStudent(Student):\n    def calculate_grade(self, marks):\n        return "A" if marks >= 70 else "B"\n\n\nclass ManagementStudent(Student):\n    def calculate_grade(self, marks):\n        return "A" if marks >= 65 else "B"\n\n\nfor student in [\n    EngineeringStudent(),\n    MedicalStudent(),\n    ManagementStudent()\n]:\n    print(student.calculate_grade(72))\n', 'polymorphism7.py': '# Bank interest polymorphism\n\nclass BankAccount:\n    def calculate_interest(self, balance):\n        pass\n\n\nclass SavingsAccount(BankAccount):\n    def calculate_interest(self, balance):\n        return balance * 0.06\n\n\nclass CurrentAccount(BankAccount):\n    def calculate_interest(self, balance):\n        return balance * 0.02\n\n\nclass FixedDepositAccount(BankAccount):\n    def calculate_interest(self, balance):\n        return balance * 0.08\n\n\nfor account in [\n    SavingsAccount(),\n    CurrentAccount(),\n    FixedDepositAccount()\n]:\n    print("Interest:", account.calculate_interest(50000))\n', 'polymorphism8.py': '# Report generation polymorphism\n\nclass Report:\n    def generate(self):\n        pass\n\n\nclass PDFReport(Report):\n    def generate(self):\n        print("PDF report generated")\n\n\nclass ExcelReport(Report):\n    def generate(self):\n        print("Excel report generated")\n\n\nclass HTMLReport(Report):\n    def generate(self):\n        print("HTML report generated")\n\n\ndef create_report(report):\n    report.generate()\n\n\nfor report in [PDFReport(), ExcelReport(), HTMLReport()]:\n    create_report(report)\n', 'polymorphism9.py': '# Distance operator overloading\n\nclass Distance:\n    def __init__(self, feet, inches):\n        self.feet = feet\n        self.inches = inches\n\n    def __add__(self, other):\n        total_inches = self.feet * 12 + self.inches\n        total_inches += other.feet * 12 + other.inches\n\n        return Distance(total_inches // 12, total_inches % 12)\n\n    def display(self):\n        print(self.feet, "feet", self.inches, "inches")\n\n\nd1 = Distance(5, 8)\nd2 = Distance(3, 6)\n\nd3 = d1 + d2\nd3.display()\n', 'polymorphism10.py': '# Student comparison operator overloading\n\nclass Student:\n    def __init__(self, name, marks):\n        self.name = name\n        self.marks = marks\n\n    def __gt__(self, other):\n        return self.marks > other.marks\n\n    def __lt__(self, other):\n        return self.marks < other.marks\n\n\ns1 = Student("Amit", 85)\ns2 = Student("Rahul", 78)\n\nprint("Amit > Rahul:", s1 > s2)\nprint("Amit < Rahul:", s1 < s2)\n', 'polymorphism11.py': '# Product comparison operator overloading\n\nclass Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n\n    def __eq__(self, other):\n        return self.price == other.price\n\n    def __gt__(self, other):\n        return self.price > other.price\n\n\np1 = Product("Laptop", 60000)\np2 = Product("Mobile", 30000)\n\nprint("Equal:", p1 == p2)\nprint("Laptop > Mobile:", p1 > p2)\n', 'polymorphism12.py': '# Online payment polymorphism\n\nclass Payment:\n    def make_payment(self, amount):\n        pass\n\n\nclass UPIPayment(Payment):\n    def make_payment(self, amount):\n        print("UPI payment:", amount)\n\n\nclass CardPayment(Payment):\n    def make_payment(self, amount):\n        print("Card payment:", amount)\n\n\nclass WalletPayment(Payment):\n    def make_payment(self, amount):\n        print("Wallet payment:", amount)\n\n\ndef pay(payment, amount):\n    payment.make_payment(amount)\n\n\nfor payment in [\n    UPIPayment(),\n    CardPayment(),\n    WalletPayment()\n]:\n    pay(payment, 1000)\n', 'polymorphism13.py': '# Person role polymorphism\n\nclass Person:\n    def display_role(self):\n        pass\n\n\nclass Student(Person):\n    def display_role(self):\n        print("Student")\n\n\nclass Faculty(Person):\n    def display_role(self):\n        print("Faculty")\n\n\nclass Administrator(Person):\n    def display_role(self):\n        print("Administrator")\n\n\npeople = [Student(), Faculty(), Administrator()]\n\nfor person in people:\n    person.display_role()\n', 'polymorphism14.py': '# Media play polymorphism\n\nclass Media:\n    def play(self):\n        pass\n\n\nclass Audio(Media):\n    def play(self):\n        print("Playing audio")\n\n\nclass Video(Media):\n    def play(self):\n        print("Playing video")\n\n\nclass Podcast(Media):\n    def play(self):\n        print("Playing podcast")\n\n\nfor media in [Audio(), Video(), Podcast()]:\n    media.play()\n', 'polymorphism15.py': '# Smart device polymorphism\n\nclass SmartDevice:\n    def turn_on(self):\n        pass\n\n    def turn_off(self):\n        pass\n\n\nclass Light(SmartDevice):\n    def turn_on(self):\n        print("Light ON")\n\n    def turn_off(self):\n        print("Light OFF")\n\n\nclass Fan(SmartDevice):\n    def turn_on(self):\n        print("Fan ON")\n\n    def turn_off(self):\n        print("Fan OFF")\n\n\nclass AC(SmartDevice):\n    def turn_on(self):\n        print("AC ON")\n\n    def turn_off(self):\n        print("AC OFF")\n\n\nclass TV(SmartDevice):\n    def turn_on(self):\n        print("TV ON")\n\n    def turn_off(self):\n        print("TV OFF")\n\n\nfor device in [Light(), Fan(), AC(), TV()]:\n    device.turn_on()\n    device.turn_off()\n', 'abstraction1.py': '# Abstract shape classes\n\nfrom abc import ABC, abstractmethod\n\nclass Shape(ABC):\n    @abstractmethod\n    def area(self):\n        pass\n\n\nclass Circle(Shape):\n    def area(self):\n        return 3.14 * 5 * 5\n\n\nclass Rectangle(Shape):\n    def area(self):\n        return 10 * 5\n\n\nclass Triangle(Shape):\n    def area(self):\n        return 0.5 * 10 * 6\n\n\nfor shape in [Circle(), Rectangle(), Triangle()]:\n    print("Area:", shape.area())\n', 'abstraction2.py': '# Abstract vehicle class\n\nfrom abc import ABC, abstractmethod\n\nclass Vehicle(ABC):\n    @abstractmethod\n    def start(self):\n        pass\n\n    @abstractmethod\n    def stop(self):\n        pass\n\n\nclass Car(Vehicle):\n    def start(self):\n        print("Car started")\n\n    def stop(self):\n        print("Car stopped")\n\n\nclass Bike(Vehicle):\n    def start(self):\n        print("Bike started")\n\n    def stop(self):\n        print("Bike stopped")\n\n\nclass Bus(Vehicle):\n    def start(self):\n        print("Bus started")\n\n    def stop(self):\n        print("Bus stopped")\n\n\nfor vehicle in [Car(), Bike(), Bus()]:\n    vehicle.start()\n    vehicle.stop()\n', 'abstraction3.py': '# Abstract bank account\n\nfrom abc import ABC, abstractmethod\n\nclass BankAccount(ABC):\n    @abstractmethod\n    def deposit(self, amount):\n        pass\n\n    @abstractmethod\n    def withdraw(self, amount):\n        pass\n\n\nclass SavingsAccount(BankAccount):\n    def __init__(self):\n        self.balance = 0\n\n    def deposit(self, amount):\n        self.balance += amount\n\n    def withdraw(self, amount):\n        if amount <= self.balance:\n            self.balance -= amount\n\n\nclass CurrentAccount(SavingsAccount):\n    pass\n\n\naccount = SavingsAccount()\naccount.deposit(10000)\naccount.withdraw(3000)\n\nprint("Balance:", account.balance)\n', 'abstraction4.py': '# Abstract food order\n\nfrom abc import ABC, abstractmethod\n\nclass FoodOrder(ABC):\n    @abstractmethod\n    def calculate_bill(self):\n        pass\n\n    @abstractmethod\n    def delivery_charge(self):\n        pass\n\n\nclass RestaurantOrder(FoodOrder):\n    def calculate_bill(self):\n        return 500\n\n    def delivery_charge(self):\n        return 0\n\n\nclass HomeDeliveryOrder(FoodOrder):\n    def calculate_bill(self):\n        return 500\n\n    def delivery_charge(self):\n        return 50\n\n\nfor order in [RestaurantOrder(), HomeDeliveryOrder()]:\n    print("Bill:", order.calculate_bill())\n    print("Delivery:", order.delivery_charge())\n', 'abstraction5.py': '# Abstract patient class\n\nfrom abc import ABC, abstractmethod\n\nclass Patient(ABC):\n    @abstractmethod\n    def calculate_bill(self):\n        pass\n\n    @abstractmethod\n    def treatment(self):\n        pass\n\n\nclass InPatient(Patient):\n    def calculate_bill(self):\n        return 5000\n\n    def treatment(self):\n        print("In-patient treatment")\n\n\nclass OutPatient(Patient):\n    def calculate_bill(self):\n        return 1000\n\n    def treatment(self):\n        print("Out-patient treatment")\n\n\nclass EmergencyPatient(Patient):\n    def calculate_bill(self):\n        return 10000\n\n    def treatment(self):\n        print("Emergency treatment")\n\n\nfor patient in [\n    InPatient(),\n    OutPatient(),\n    EmergencyPatient()\n]:\n    print("Bill:", patient.calculate_bill())\n    patient.treatment()\n', 'abstraction6.py': '# Abstract transport fare\n\nfrom abc import ABC, abstractmethod\n\nclass Transport(ABC):\n    @abstractmethod\n    def calculate_fare(self, distance):\n        pass\n\n\nclass Bus(Transport):\n    def calculate_fare(self, distance):\n        return distance * 2\n\n\nclass Train(Transport):\n    def calculate_fare(self, distance):\n        return distance * 3\n\n\nclass Taxi(Transport):\n    def calculate_fare(self, distance):\n        return distance * 10\n\n\nclass Flight(Transport):\n    def calculate_fare(self, distance):\n        return distance * 20\n\n\nfor transport in [Bus(), Train(), Taxi(), Flight()]:\n    print("Fare:", transport.calculate_fare(100))\n', 'abstraction7.py': '# Abstract question evaluation\n\nfrom abc import ABC, abstractmethod\n\nclass Question(ABC):\n    @abstractmethod\n    def evaluate_answer(self, answer):\n        pass\n\n\nclass MCQQuestion(Question):\n    def evaluate_answer(self, answer):\n        return answer == "A"\n\n\nclass TrueFalseQuestion(Question):\n    def evaluate_answer(self, answer):\n        return answer.lower() == "true"\n\n\nclass DescriptiveQuestion(Question):\n    def evaluate_answer(self, answer):\n        return len(answer.strip()) > 10\n\n\nprint("MCQ:", MCQQuestion().evaluate_answer("A"))\nprint("True/False:", TrueFalseQuestion().evaluate_answer("True"))\nprint("Descriptive:", DescriptiveQuestion().evaluate_answer("This is an answer"))\n', 'abstraction8.py': '# Abstract authentication\n\nfrom abc import ABC, abstractmethod\n\nclass Authentication(ABC):\n    @abstractmethod\n    def authenticate(self):\n        pass\n\n\nclass PasswordAuthentication(Authentication):\n    def authenticate(self):\n        print("Password authentication successful")\n\n\nclass OTPAuthentication(Authentication):\n    def authenticate(self):\n        print("OTP authentication successful")\n\n\nclass BiometricAuthentication(Authentication):\n    def authenticate(self):\n        print("Biometric authentication successful")\n\n\nfor auth in [\n    PasswordAuthentication(),\n    OTPAuthentication(),\n    BiometricAuthentication()\n]:\n    auth.authenticate()\n', 'abstraction9.py': '# Abstract cloud storage\n\nfrom abc import ABC, abstractmethod\n\nclass CloudStorage(ABC):\n    @abstractmethod\n    def upload_file(self):\n        pass\n\n    @abstractmethod\n    def download_file(self):\n        pass\n\n    @abstractmethod\n    def delete_file(self):\n        pass\n\n\nclass GoogleDrive(CloudStorage):\n    def upload_file(self):\n        print("File uploaded to Google Drive")\n\n    def download_file(self):\n        print("File downloaded from Google Drive")\n\n    def delete_file(self):\n        print("File deleted from Google Drive")\n\n\nstorage = GoogleDrive()\n\nstorage.upload_file()\nstorage.download_file()\nstorage.delete_file()\n', 'abstraction10.py': '# Abstract appointment\n\nfrom abc import ABC, abstractmethod\n\nclass Appointment(ABC):\n    @abstractmethod\n    def book_appointment(self):\n        pass\n\n    @abstractmethod\n    def calculate_fee(self):\n        pass\n\n\nclass GeneralAppointment(Appointment):\n    def book_appointment(self):\n        print("General appointment booked")\n\n    def calculate_fee(self):\n        return 500\n\n\nclass SpecialistAppointment(Appointment):\n    def book_appointment(self):\n        print("Specialist appointment booked")\n\n    def calculate_fee(self):\n        return 1000\n\n\nclass EmergencyAppointment(Appointment):\n    def book_appointment(self):\n        print("Emergency appointment booked")\n\n    def calculate_fee(self):\n        return 2000\n\n\nfor appointment in [\n    GeneralAppointment(),\n    SpecialistAppointment(),\n    EmergencyAppointment()\n]:\n    appointment.book_appointment()\n    print("Fee:", appointment.calculate_fee())\n'}

